  const cardEl = pick([
    'input[name="user"]',
    'input[name="username"]',
    'input[name="barcode"]',
    'input[id="user"]',
    'input[id="username"]',
  ]);
  const pinEl = pick([
    'input[name="pass"]',
    'input[name="password"]',
    'input[name="pin"]',
    'input[type="password"]',
  ]);

  if (!cardEl || !pinEl) {
    console.warn(`${TAG} Could not find login form fields.`);
    return;
  }

  const setValue = (el, value) => {
    const setter = Object.getOwnPropertyDescriptor(
      window.HTMLInputElement.prototype,
      "value",
    ).set;
    setter.call(el, value);
    el.dispatchEvent(new Event("input", { bubbles: true }));
    el.dispatchEvent(new Event("change", { bubbles: true }));
  };

  // Trim defensively. A trailing space saved with the PIN submits verbatim and
  // reads as "card/PIN incorrect" even when the credentials are right.
  setValue(cardEl, String(libraryCard).trim());
  setValue(pinEl, String(libraryPin).trim());

  // Mark the attempt BEFORE submitting so the post-failure reload is guarded.
  sessionStorage.setItem(ATTEMPT_KEY, "1");

  const form = cardEl.closest("form");
  const submitEl =
    (form &&
      form.querySelector(
        'input[type="submit"], button[type="submit"], button:not([type])',
      )) ||
    document.querySelector('input[type="submit"], button[type="submit"]');

  if (submitEl) {
    submitEl.click();
  } else if (form) {
    form.submit();
  }
})();

input.old_string:
// Re-entering credentials clears any failure/cooldown/rejection block so the
// corrected card/PIN get a fresh attempt.
chrome.runtime.sendMessage({ type: "creds-updated" });

input.new_string:
// Re-entering credentials re-enables auto-login (it disables itself for the
// session after a failed attempt) so the corrected card/PIN get a fresh try.
chrome.runtime.sendMessage({ type: "creds-updated" });

